package com.mfg.mes.entity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="mes_work_order",catalog="src_mes") @Getter @Setter @NoArgsConstructor public class WorkOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="work_order_no")private String workOrderNo;@Column(name="prod_order_no")private String prodOrderNo;@Column(name="product_code")private String productCode;@Column(name="op_seq")private Integer opSeq;@Column(name="operation_code")private String operationCode;@Column(name="operation_name")private String operationName;@Column(name="equipment_code")private String equipmentCode;@Column(name="plan_qty")private BigDecimal planQty;@Column(name="completed_qty")private BigDecimal completedQty=BigDecimal.ZERO;@Column(name="qualified_qty")private BigDecimal qualifiedQty=BigDecimal.ZERO;@Column(name="scrap_qty")private BigDecimal scrapQty=BigDecimal.ZERO;@Column(name="wo_status")private String status="CREATED";@Column(name="actual_start_time")private LocalDateTime actualStartTime;@Column(name="actual_end_time")private LocalDateTime actualEndTime;}
